import { describe, expect, it } from 'vitest'
import fixtures from './__fixtures__/messages.json' with { type: 'json' }
import {
  designationText,
  fromHtml,
  fromPlain,
  messageFromJson,
  references,
  toMarkdown,
  toPlain,
  withDesignationText,
  type DisplayText,
} from './message.js'

/**
 * Parity with tricc_oo. `__fixtures__/messages.json` is generated by tricc_oo's own
 * `load_display_text` and `serialize_injection_for_js_text`; regenerate it there when the
 * rules change, and this test says where the two disagree.
 */
describe('display text matches tricc_oo', () => {
  for (const { html, tree, markdown } of fixtures as { html: string; tree: DisplayText; markdown: string }[]) {
    it(`parses ${JSON.stringify(html)}`, () => {
      expect(fromHtml(html)).toEqual(tree)
      expect(toMarkdown(fromHtml(html))).toBe(markdown)
    })
  }
})

describe('display text', () => {
  it('keeps plain text plain, and splits ${} tokens', () => {
    expect(fromPlain('Weight (kg)')).toBe('Weight (kg)')
    expect(fromPlain('Give ${dose} mg')).toEqual({
      type: 'message',
      children: [
        { type: 'text', value: 'Give ' },
        { type: 'interp', name: 'dose' },
        { type: 'text', value: ' mg' },
      ],
    })
  })

  it('reads its own JSON back, and rejects anything else', () => {
    const text = fromHtml('<b>Give ${dose}</b><ul><li>with food</li></ul>')
    expect(messageFromJson(JSON.parse(JSON.stringify(text)))).toEqual(text)
    expect(() => messageFromJson({ type: 'message', children: [{ type: 'script' }] })).toThrow()
  })

  it('lists references in reading order and renders a plain form', () => {
    const text = fromHtml('<b>Give ${dose}</b> to ${name}')
    expect(references(text)).toEqual(['dose', 'name'])
    expect(toPlain(text)).toBe('Give ${dose} to ${name}')
  })

  it('stores Markdown in the value, and the tree only when there is structure', () => {
    const base = { language: 'en', value: '' }
    const plain = withDesignationText(base, 'Weigh the child')
    expect(plain).toEqual({ language: 'en', value: 'Weigh the child' })
    const rich = withDesignationText(base, fromHtml('<b>Give ${dose} mg</b>'))
    expect(rich.value).toBe('**Give ${dose} mg**')
    expect(rich.extension).toHaveLength(1)
    expect(designationText(rich)).toEqual(fromHtml('<b>Give ${dose} mg</b>'))
    // Back to plain: the tree goes, other extensions stay.
    const scoped = {
      ...rich,
      extension: [...rich.extension!, { url: 'https://tricc.org/StructureDefinition/designation-intervention', valueCode: 'iv' }],
    }
    expect(withDesignationText(scoped, 'Plain again').extension).toEqual([
      { url: 'https://tricc.org/StructureDefinition/designation-intervention', valueCode: 'iv' },
    ])
  })
})

describe('font colour', () => {
  const red = {
    type: 'message' as const,
    children: [
      { type: 'mark' as const, kind: 'color' as const, color: '#d32f2f', children: [{ type: 'text' as const, value: 'Danger' }] },
      { type: 'text' as const, value: ' sign' },
    ],
  }

  it('renders as an inline span ODK and CHT understand', () => {
    expect(toMarkdown(red)).toBe('<span style="color:#d32f2f">Danger</span> sign')
    expect(toPlain(red)).toBe('Danger sign')
  })

  it('round-trips through JSON, and refuses a value that is not a colour', () => {
    expect(messageFromJson(JSON.parse(JSON.stringify(red)))).toEqual(red)
    const bad = structuredClone(red) as unknown as { children: { color?: string }[] }
    bad.children[0]!.color = 'red;background:url(x)'
    expect(() => messageFromJson(bad)).toThrow()
  })
})

